// lib/api/inference.ts

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";

export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

export interface InferenceStartResult {
  pid?: number;
  key?: string;
}

/**
 * shared helper (reuse same pattern)
 */
async function fetchJsonWithTimeout(
  input: RequestInfo,
  init?: RequestInit,
  timeoutMs = 8000,
): Promise<{ ok: boolean; status: number; body: any | null }> {
  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const res = await fetch(input, {
      ...(init || {}),
      signal: controller.signal,
    });

    const text = await res.text().catch(() => "");
    let body = null;

    try {
      if (text) body = JSON.parse(text);
    } catch {
      body = text;
    }

    return { ok: res.ok, status: res.status, body };
  } finally {
    clearTimeout(id);
  }
}

export async function startInference(
  params: {
    sensorDbId?: string;
    rtspUrl?: string;
    confidence?: number;
    iou?: number;
    showLabels?: boolean;
    showConfidence?: boolean;
  },
  timeoutMs = 10000,
): Promise<ApiResponse<InferenceStartResult>> {
  const { sensorDbId, rtspUrl } = params;

  if (!sensorDbId && !rtspUrl) {
    return { success: false, error: "sensorDbId or rtspUrl is required" };
  }

  try {
    const url = `${API_BASE_URL}/api/inference/start`;

    const payload: any = {
      ...params,
    };

    const { ok, status, body } = await fetchJsonWithTimeout(
      url,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
        credentials: "include",
      },
      timeoutMs,
    );

    if (!ok) {
      const errMsg =
        (body &&
          (body.error || (typeof body === "string" ? body : undefined))) ||
        `Server returned ${status}`;

      return { success: false, error: errMsg, message: body?.message };
    }

    let result: InferenceStartResult = {};

    if (body) {
      result = {
        pid: typeof body.pid === "number" ? body.pid : undefined,
        key:
          typeof body.key === "string"
            ? body.key
            : body.sensorDbId || undefined,
      };
    }

    return {
      success: true,
      data: result,
      message: body?.message || "Inference started",
    };
  } catch (err) {
    const errMsg =
      err instanceof Error
        ? err.name === "AbortError"
          ? "Request timed out"
          : err.message
        : "Network error";

    console.error("startInference error:", err);
    return { success: false, error: errMsg };
  }
}

export async function stopInference(
  params: {
    sensorDbId?: string;
    rtspUrl?: string;
  },
  timeoutMs = 8000,
): Promise<ApiResponse> {
  if (!params.sensorDbId && !params.rtspUrl) {
    return { success: false, error: "Provide sensorDbId or rtspUrl" };
  }

  try {
    const url = `${API_BASE_URL}/api/inference/stop`;

    const { ok, status, body } = await fetchJsonWithTimeout(
      url,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(params),
        credentials: "include",
      },
      timeoutMs,
    );

    if (!ok) {
      const errMsg =
        (body &&
          (body.error || (typeof body === "string" ? body : undefined))) ||
        `Server returned ${status}`;

      return { success: false, error: errMsg, message: body?.message };
    }

    return {
      success: true,
      message: body?.message || "Inference stopped",
    };
  } catch (err) {
    const errMsg =
      err instanceof Error
        ? err.name === "AbortError"
          ? "Request timed out"
          : err.message
        : "Network error";

    console.error("stopInference error:", err);
    return { success: false, error: errMsg };
  }
}
